(()=>{const cards=[...document.querySelectorAll('.photo-card')],filters=[...document.querySelectorAll('[data-filter]')],modal=document.querySelector('.gallery-modal');if(!modal)return;const picture=modal.querySelector('img'),title=modal.querySelector('.modal-title'),count=modal.querySelector('.modal-count');let current=0,opener;const visible=()=>cards.filter(c=>!c.hidden);function show(index){const items=visible();current=(index+items.length)%items.length;const img=items[current].querySelector('img');picture.src=img.src;picture.alt=img.alt;title.textContent=items[current].dataset.title;count.textContent=`${current+1} / ${items.length} — AI生成の掲載サンプル`}
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));cards.forEach(c=>c.hidden=button.dataset.filter!=='all'&&c.dataset.category!==button.dataset.filter);document.querySelector('.photo-count').textContent=`${visible().length}枚の写真を表示 / すべて同じコンセプト住宅` }));cards.forEach(card=>card.querySelector('button').addEventListener('click',e=>{opener=e.currentTarget;show(visible().indexOf(card));modal.showModal()}));modal.querySelector('[data-close]').addEventListener('click',()=>modal.close());modal.querySelector('[data-prev]').addEventListener('click',()=>show(current-1));modal.querySelector('[data-next]').addEventListener('click',()=>show(current+1));modal.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}});modal.addEventListener('close',()=>opener?.focus());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}})})();
